hudson.tasks.Shell.command:
#!/bin/bash
echo "Run Lintian"
cd repo version=$(dpkg-parsechangelog -S version) epochless_version=${version##*:} source_name=$(dpkg-parsechangelog -S source) export_dir="../build" source_changes="${export_dir}/${source_name}_${epochless_version}_source.changes" arch=$(dpkg-architecture -qDEB_HOST_ARCH) arch_changes="${export_dir}/${source_name}_${epochless_version}_${arch}.changes"
(lintian -I --pedantic --show-overrides "${source_changes}"; lintian -I --pedantic --show-overrides "${arch_changes}") 2>&1 | \ tee "${export_dir}/lintian.log" | lintian2junit.py -o "${export_dir}/lintian.xml";
